plugins {
    // Apply the java-library plugin for API and implementation separation.
    id("java")
    id("org.springframework.boot") version "3.3.4"
    id("io.spring.dependency-management") version "1.1.6"
}

group = "com.example"
version = "0.0.1-SNAPSHOT"


// Use Maven Central for resolving dependencies.
repositories { 
    mavenCentral()
}

dependencies {

	// Add the Web starter to build APIs/Web endpoints for tickets.
	 implementation("org.springframework.boot:spring-boot-starter-web")
	 
	// Mongo
	 implementation("org.springframework.boot:spring-boot-starter-data-mongodb")
	
    // Use JUnit Jupiter for testing.
    testImplementation(libs.junit.jupiter)

    testRuntimeOnly("org.junit.platform:junit-platform-launcher")
	
	//Testing Support
    testImplementation("org.springframework.boot:spring-boot-starter-test")
    testRuntimeOnly("org.junit.platform:junit-platform-launcher")

    // This dependency is exported to consumers, that is to say found on their compile classpath.
    implementation("org.apache.commons:commons-math3:3.6.1")

    // This dependency is used internally, and not exposed to consumers on their own compile classpath.
    implementation(libs.guava)
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        // Fixed: Use standard .set() provider syntax required by Kotlin DSL
        languageVersion.set(JavaLanguageVersion.of(21))
    }
}

allprojects {
    // Keeps your standard JUnit 5 setup for tests, but removes the broken URI overrides
    tasks.withType<Test>().configureEach {
        useJUnitPlatform()
    }
}